import "./Admin.css";
import { useEffect, useState } from "react";

function Admin() {
  const [inquiries, setInquiries] = useState([]);
  const [search, setSearch] = useState(""); // Search state
  const [currentPage, setCurrentPage] = useState(1);
  const [inquiriesPerPage, setInquiriesPerPage] = useState(5); // Rows per page state
  const [sortOrder, setSortOrder] = useState("desc"); // New: sort by date, default descending

  // Fetch inquiries from backend
  const fetchInquiries = async () => {
    try {
      const response = await fetch("http://127.0.0.1:8000/inquiries");
      const data = await response.json();
      setInquiries(data);
    } catch (error) {
      console.error("Error fetching inquiries:", error);
    }
  };

  // Delete inquiry by id
  const deleteInquiry = async (id) => {
    try {
      const response = await fetch(`http://127.0.0.1:8000/inquiry/${id}`, {
        method: "DELETE",
      });
      if (response.ok) {
        alert("Inquiry deleted successfully!");
        fetchInquiries(); // Refresh list
      } else {
        const err = await response.json();
        alert(err.detail);
      }
    } catch (error) {
      console.error("Error deleting inquiry:", error);
    }
  };

  useEffect(() => {
    fetchInquiries();
  }, []);

  // Handle search input change
  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    setCurrentPage(1);
  };

  // Handle rows per page change
  const handleRowsChange = (e) => {
    setInquiriesPerPage(Number(e.target.value));
    setCurrentPage(1);
  };

  // Handle sort order change
  const toggleSortOrder = () => {
    setSortOrder(sortOrder === "asc" ? "desc" : "asc");
  };

  // Filtered and sorted inquiries
  const filteredInquiries = inquiries
    .filter(
      (inq) =>
        inq.name.toLowerCase().includes(search.toLowerCase()) ||
        inq.mobile.includes(search)
    )
    .sort((a, b) => {
      const dateA = new Date(a.date);
      const dateB = new Date(b.date);
      return sortOrder === "asc" ? dateA - dateB : dateB - dateA;
    });

  // Pagination calculations
  const indexOfLastInquiry = currentPage * inquiriesPerPage;
  const indexOfFirstInquiry = indexOfLastInquiry - inquiriesPerPage;
  const currentInquiries = filteredInquiries.slice(
    indexOfFirstInquiry,
    indexOfLastInquiry
  );
  const totalPages = Math.ceil(filteredInquiries.length / inquiriesPerPage);

  // Next / Previous button handlers
  const handleNext = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1);
  };
  const handlePrev = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1);
  };

  return (
    <div>
      <h1>Admin Panel - Inquiries</h1>

      {/* Search Input */}
      <input
        type="text"
        placeholder="Search by name or mobile..."
        value={search}
        onChange={handleSearchChange}
        style={{ marginBottom: "15px", padding: "5px", width: "250px" }}
      />

      {/* Rows per page dropdown */}
      <div style={{ marginBottom: "10px" }}>
        <label>Rows per page: </label>
        <select value={inquiriesPerPage} onChange={handleRowsChange}>
          <option value={5}>5</option>
          <option value={10}>10</option>
          <option value={15}>15</option>
          <option value={20}>20</option>
        </select>
      </div>

      {/* Sort button */}
      <div style={{ marginBottom: "10px" }}>
        <button onClick={toggleSortOrder}>
          Sort by Date: {sortOrder === "asc" ? "Oldest First" : "Newest First"}
        </button>
      </div>

      {inquiries.length === 0 ? (
        <p>No inquiries found.</p>
      ) : (
        <>
          <table border="1" cellPadding="10">
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>Mobile</th>
                <th>Message</th>
                <th>Date</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {currentInquiries.map((inq) => (
                <tr key={inq._id}>
                  <td>{inq.name}</td>
                  <td>{inq.email}</td>
                  <td>{inq.mobile}</td>
                  <td>{inq.message}</td>
                  <td>{new Date(inq.date).toLocaleString()}</td>
                  <td>
                    <button onClick={() => deleteInquiry(inq._id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Pagination */}
          <div style={{ marginTop: "10px" }}>
            <button
              onClick={handlePrev}
              disabled={currentPage === 1}
              style={{
                padding: "5px 10px",
                marginRight: "5px",
                cursor: currentPage === 1 ? "not-allowed" : "pointer",
              }}
            >
              Previous
            </button>
            <button
              onClick={handleNext}
              disabled={currentPage === totalPages}
              style={{
                padding: "5px 10px",
                cursor: currentPage === totalPages ? "not-allowed" : "pointer",
              }}
            >
              Next
            </button>
            <span style={{ marginLeft: "10px" }}>
              Page {currentPage} of {totalPages}
            </span>
          </div>
        </>
      )}
    </div>
  );
}

export default Admin;
